| As per CERN-OHL-W v2 section 4.1, should You produce hardware based on these |
| sources, You must maintain the Source Location visible on the external case  |
| of the FIR_x2 or other products you make using this source.                  |
--------------------------------------------------------------------------------
*
-----------------------------------------------------------------------------*/
`default_nettype none

module SPROM_CONT #(
    /* Parameter Definition */
    parameter ROM_ADDR_WIDTH = 9 // Default: 9bits (511 - 0)
)
(
    /* Input Definition */
    input  wire MCLK_I,
    input  wire BCK_I,
    input  wire LRCK_I,
    input  wire NRST_I, // Active Low

    /* Output Definition */
    output wire [ROM_ADDR_WIDTH-1:0] CADDR_O,
    output wire                      LRCKx_O,
    output wire                      BCKx_O
);

    /* Internal Wire/Register Definition */
    reg BCK_REG  = 1'b0;
    reg LRCK_REG = 1'b0;

    reg BCKx_REG  = 1'b1;
    reg LRCKx_REG = 1'b1;

    reg [ROM_ADDR_WIDTH-1:0] CADDR_REG  = {ROM_ADDR_WIDTH{1'b0}};
    reg [ROM_ADDR_WIDTH-1:0] CADDRO_REG = {ROM_ADDR_WIDTH{1'b0}};

    /* RTL */
    always @ (posedge MCLK_I) begin
        /* Read BCK & LRCK */
        BCK_REG  <= BCK_I;
        LRCK_REG <= LRCK_I;

        /* Update Address */
        if (LRCK_I & ~LRCK_REG == 1'b1) begin
            /* Change Initial Address */
            CADDR_REG <= {{(ROM_ADDR_WIDTH-1){1'b0}}, 1'b1};
        end else begin
            /* Change Odd & Even */
            CADDR_REG <= {(CADDR_REG[ROM_ADDR_WIDTH-1:1] + 1'b1), LRCK_I};
        end

        /* Output Pipeline with positive edge. */
        CADDRO_REG <= {ROM_ADDR_WIDTH{1'b1}} - CADDR_REG;
        LRCKx_REG  <= CADDR_REG[ROM_ADDR_WIDTH-1];
        BCKx_REG   <= (ROM_ADDR_WIDTH >= 8) ? CADDR_REG[ROM_ADDR_WIDTH-7] : 1'b0;
    end

    /* Output Assign */
    assign CADDR_O = CADDRO_REG;
    assign LRCKx_O = LRCKx_REG;
    assign BCKx_O  = (ROM_ADDR_WIDTH >= 7) ? BCKx_REG : MCLK_I; // Change BCK Generation

endmodule

`default_nettype wire

/*-----------------------------------------------------------------------------
* MULT.v
*
* PCM DATA & Digital Filter Multiplier w/ input & output register.
*
* Version: 2.02
* Author : AUDIY
* Date   : 2026/04/13
*
* Port
*   Input
*       MCLK_I     : Master Clock Input
*       DATA_I     : PCM Data Input
*       COEF_I     : Filter Coefficient Input
*       LRCKx2_I   : Oversampled LRCK input
*       BCKx2_I    : Oversampled BCK input
*       NRST_I     : Reset Input (Active Low)
*
*   Output
*       DATA_O     : Multiplied Data Output
*       LRCKx2_O   : Oversampled LRCK Output (w/ delay)
*       BCKx2_O    : Oversampled BCK Output (w/ delay)
*
* Parameter
*       DATA_WIDTH : PCM Data input bitwise.
*       COEF_WIDTH : Coefficient bitwise.
*
* License
--------------------------------------------------------------------------------
| Copyright AUDIY 2023 - 2026.                                                 |
|                                                                              |
| This source describes Open Hardware and is licensed under the CERN-OHL-W v2. |
|                                                                              |
| You may redistribute and modify this source and make products using it under |
| the terms of the CERN-OHL-W v2 (https://cern.ch/cern-ohl).                   |
|                                                                              |
| This source is distributed WITHOUT ANY EXPRESS OR IMPLIED WARRANTY,          |
| INCLUDING OF MERCHANTABILITY, SATISFACTORY QUALITY AND FITNESS FOR A         |
| PARTICULAR PURPOSE. Please see the CERN-OHL-W v2 for applicable conditions.  |
|                                                                              |
| Source location: https://github.com/AUDIY/FIR_x2                             |
|                                                                              |
| As per CERN-OHL-W v2 section 4.1, should You produce hardware based on these |
| sources, You must maintain the Source Location visible on the external case  |
| of the FIR_x2 or other products you make using this source.                  |
--------------------------------------------------------------------------------
*
-----------------------------------------------------------------------------*/
`default_nettype none

module MULT #(
    /* Parameter Definition */
    parameter DATA_WIDTH = 32,
    parameter COEF_WIDTH = 16,
    parameter ROM_ADDR_WIDTH = 9
)
(
    /* Input Port Definition */
    input  wire                                    MCLK_I,
    input  wire signed [DATA_WIDTH-1:0]            DATA_I,
    input  wire signed [COEF_WIDTH-1:0]            COEF_I,
    input  wire                                    LRCKx2_I,
    input  wire                                    BCKx2_I,
    input  wire                                    NRST_I,

    /* Output Port Definition */
    output wire signed [DATA_WIDTH+COEF_WIDTH-1:0] DATA_O,
    output wire                                    LRCKx2_O,
    output wire                                    BCKx2_O
);

    /* Internal Wire/Register Definition */
    reg  LRCKx2_p1 = 1'b0;
    reg  LRCKx2_p2 = 1'b0;
    reg  BCKx2_p1  = 1'b0;
    reg  BCKx2_p2  = 1'b0;
    reg  signed [DATA_WIDTH-1:0]            DATAI_p1 = {DATA_WIDTH{1'b0}};
    reg  signed [COEF_WIDTH-1:0]            COEF_p1  = {COEF_WIDTH{1'b0}};
    reg  signed [DATA_WIDTH+COEF_WIDTH-1:0] DATAO_p1 = {(DATA_WIDTH+COEF_WIDTH){1'b0}};

    wire signed [DATA_WIDTH+COEF_WIDTH-1:0] MULT_WIRE; 

    /* RTL */
    always @ (posedge MCLK_I) begin
        LRCKx2_p1 <= LRCKx2_I;
        LRCKx2_p2 <= LRCKx2_p1;
        BCKx2_p1  <= (ROM_ADDR_WIDTH >= 8) ? BCKx2_I : 1'b0;
        BCKx2_p2  <= (ROM_ADDR_WIDTH >= 8) ? BCKx2_p1 : 1'b0;
        DATAI_p1  <= DATA_I;
        COEF_p1   <= COEF_I;
        DATAO_p1  <= (NRST_I == 1'b0) ? {(DATA_WIDTH+COEF_WIDTH){1'b0}} : MULT_WIRE;
    end

    // Note: Multiplier assign recommendation differs depends on FPGA vendor.
    //       Please check the HDL coding guideline of the target FPGA.
    assign MULT_WIRE = DATAI_p1 * COEF_p1;

    assign LRCKx2_O  = LRCKx2_p2;
    assign BCKx2_O   = (ROM_ADDR_WIDTH >= 8) ? BCKx2_p2 : MCLK_I;
    assign DATA_O    = DATAO_p1;

endmodule

`default_nettype wire

