`default_nettype none

`timescale 1 ns / 1 ps

module DPRAM_CONT_TB();

    /* Parameter Definition */
    parameter ADDR_WIDTH = 8;

    /* Register/Wire Definition for Test bench */
    reg  MCLK_I = 1'b0;
    wire BCK_I;
    wire LRCK_I;
    reg  NRST_I = 1'b1;

    wire WEN_O;
    wire [ADDR_WIDTH-1:0] WADDR_O;
    wire [ADDR_WIDTH-1:0] RADDR_O;
    wire REN_O;

    reg [8:0] MCLK_REG = {9{1'b0}};

    /* DPRAM_CONT module (EUT) */
    DPRAM_CONT #(
        .ADDR_WIDTH(ADDR_WIDTH)
    ) u1 (
        .MCLK_I(MCLK_I),
        .LRCK_I(LRCK_I),
        .NRST_I(NRST_I),
        .WEN_O(WEN_O),
        .WADDR_O(WADDR_O),
        .REN_O(REN_O),
        .RADDR_O(RADDR_O)
    );

    /* Test bench */
    initial begin
        $dumpfile("DPRAM_CONT_TB.vcd");
        $dumpvars(0, DPRAM_CONT_TB);

        #400000 $finish;

    end

    always begin
        #1 MCLK_I <= ~MCLK_I;
    end

    always @ (posedge MCLK_I) begin
        MCLK_REG <= MCLK_REG + 1'b1;
    end

    assign BCK_I  = MCLK_REG[2];
    assign LRCK_I = MCLK_REG[8];

    always begin
        #4989 NRST_I <= 1'b0;
        #512  NRST_I <= 1'b1;
    end

endmodule

`default_nettype wire
